arguments.command:
sed -i '$d' tests/deliver_test.sh
cat >> tests/deliver_test.sh <<'EOF'
[ "$(bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "default plan"; fail=1; }
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] || { echo "RELAY_ATTEMPTS plan"; fail=1; }
[ "$(RELAY_SLEEP=echo bash bin/deliver false | grep -c '^attempt ')" = 4 ] || { echo "4 attempts"; fail=1; }
exit $fail
EOF
sed -i '0,/^## 3.4.1/s//## Unreleased\n\n- deliver: follows ADR-0009 (4 attempts, waits 3\/9\/27 s) and reads the count from `RELAY_ATTEMPTS` as in the runbook (RLY-731)\n\n## 3.4.1/' CHANGELOG.md
cat docs/design/delivery.md | tail -8; head -9 CHANGELOG.md; bash scripts/verify.sh; git status --short

